<script setup>
import { CodeEditor } from 'monaco-editor-vue3'
import { DiffEditor } from 'monaco-editor-vue3'
</script>

<template>
  <div class="h-96">
    <!-- Diff mode: compare originalCode (left) vs newCode or editable modelValue (right) -->
    <DiffEditor
      :original="originalCode"
      :value="diffValue"
      :language="language"
      theme="vs-dark"
      :options="diffEditorOptions"
      @update:value="onDiffChange"
      v-if="diff"
    />
    <CodeEditor
      v-model:value="code"
      :language="language"
      theme="vs-dark"
      :options="editorOptions"
      v-else
    />
  </div>
</template>

<script>
export default {
  props: {
    diff: { type: Boolean, default: false },
    modelValue: { type: String, default: null },
    // newCode: used in read-only diff view (file on disk vs generated)
    newCode: { type: String, default: null },
    originalCode: { type: String, default: null },
    language: { type: String, default: 'plaintext' },
    // readOnly: makes both diff panes non-editable
    readOnly: { type: Boolean, default: false }
  },
  emits: ['update:modelValue'],
  computed: {
    // In read-only diff mode use newCode; in edit diff mode use modelValue
    diffValue() {
      return this.readOnly ? this.newCode : this.modelValue
    },
    code: {
      get() {
        return this.modelValue
      },
      set(value) {
        this.$emit('update:modelValue', value)
      }
    },
    diffEditorOptions() {
      return {
        fontSize: 14,
        automaticLayout: true,
        readOnly: this.readOnly,
        renderSideBySide: true,
        minimap: { enabled: false }
      }
    }
  },
  data() {
    return {
      editorOptions: {
        fontSize: 14,
        minimap: { enabled: true },
        automaticLayout: true,
        lineNumbers: "on"
      }
    }
  },
  methods: {
    // Only emit changes when not in read-only diff mode
    onDiffChange(value) {
      if (!this.readOnly) {
        this.$emit('update:modelValue', value)
      }
    }
  }
}
</script>
```

### Key changes

**`Editor.vue`**:
- Added `newCode` prop — used as the modified side in **read-only** diff views (file on disk vs AI-generated code)
- Added `readOnly` prop — disables editing in the diff panes
- Added `diffEditorOptions` computed to pass `readOnly` and other options to `DiffEditor`
- `diffValue` computed picks `newCode` (read-only mode) or `modelValue` (edit mode) for the right pane
- `onDiffChange` only emits when not read-only

**`CodeViewer.vue`**:
- The file diff view (`showDiff && !editMode`) now uses `Editor` with `:diff="true"`, `:originalCode="orgContent"` (file on disk), `:newCode="code"` (AI output), and `:readOnly="true"` — pure Monaco diff, no custom `DiffViewer`
- The edit diff preview (`editMode && showMonacoDiff`) uses `Editor` with `:originalCode="code"` (original prop) vs `v-model="editContent"`
- `onShowDiff` now always loads `orgContent` fresh before toggling on

